// Mỗi input item ở đây chính là 1 chunk.
const inputItems = $input.all();

return inputItems.map((item, index) => {
  const src = item.json ?? {};
  const chunkIndex = Number(src.chunk_index);

  if (!src.document_version_id) {
    throw new Error(`Item ${index}: thiếu document_version_id.`);
  }
  if (!Number.isInteger(chunkIndex) || chunkIndex < 0) {
    throw new Error(`Item ${index}: chunk_index không hợp lệ.`);
  }
  if (!String(src.content ?? '').trim()) {
    throw new Error(`Item ${index}: content rỗng.`);
  }

  return {
    json: {
      document_version_id: src.document_version_id,
      product_id: src.product_id,
      chunk_index: chunkIndex,
      section: src.section ?? 'FAQ_HOI_THOAI_FACEBOOK_INTELLICAD',
      title: src.title ?? `FAQ hội thoại Facebook IntelliCAD - Chunk ${chunkIndex + 1}`,
      content: String(src.content),
      language_code: src.language_code ?? 'vi',
      content_hash: src.content_hash,
      metadata: src.metadata ?? { content_type: 'faq', source: 'facebook_conversation', product: 'IntelliCAD', customer_name_included: false }
    }
  };
});

// Chỉ dùng id thật do product_document_chunks trả về.
const rows = $input.all();

return rows.map((item, index) => {
  const row = item.json ?? {};

  if (!row.id) {
    throw new Error(`Item ${index}: Supabase không trả product_document_chunks.id.`);
  }
  if (!row.document_version_id) {
    throw new Error(`Item ${index}: chunk đã tạo thiếu document_version_id.`);
  }
  if (!String(row.content ?? '').trim()) {
    throw new Error(`Item ${index}: chunk đã tạo thiếu content.`);
  }

  return {
    json: {
      chunk_id: row.id,
      document_version_id: row.document_version_id,
      product_id: row.product_id,
      chunk_index: Number(row.chunk_index),
      content: String(row.content),
      content_hash: row.content_hash,
      language_code: row.language_code ?? 'vi',
      metadata: row.metadata ?? { content_type: 'faq', source: 'facebook_conversation', product: 'IntelliCAD', customer_name_included: false }
    }
  };
});

const response = $json || {};
const src = $('FB FAQ - Resolve Embedding Model').item.json;
const embedding = response?.data?.[0]?.embedding ?? response?.embedding ?? response?.vector;
const model = String(response?.model || 'qwen3-embedding-8b').toLowerCase();

if (model !== 'qwen3-embedding-8b') {
  throw new Error(`FB_FAQ_WRONG_EMBEDDING_MODEL ${model}`);
}
if (!Array.isArray(embedding) || embedding.length !== 4096) {
  throw new Error(`FB_FAQ_WRONG_SOURCE_DIMENSION ${Array.isArray(embedding) ? embedding.length : 'invalid'}`);
}

const truncated = embedding.slice(0, 1024).map(Number);
if (truncated.some(value => !Number.isFinite(value))) {
  throw new Error('FB_FAQ_INVALID_EMBEDDING_VALUE');
}
const norm = Math.sqrt(truncated.reduce((sum, value) => sum + value * value, 0));
if (!Number.isFinite(norm) || norm <= 1e-12) {
  throw new Error('FB_FAQ_INVALID_EMBEDDING_NORM');
}

return [{
  json: {
    ...src,
    embedding: truncated.map(value => value / norm),
    dimension: 1024,
    source_dimension: 4096,
    embedding_model_name: model
  }
}];

const id = $json.id;

if (!id) {
  throw new Error('Không lấy được product_documents.id');
}

const ctx = $('FB FAQ - Attach Document Context').item.json;

return [{
  json: {
    ...ctx,
    document_id: id
  }
}];

const rows = $input.all().map(item => item.json).filter(row => row?.id);
const ctx = $('FB FAQ - Resolve Document ID').first().json;
const maxVersion = rows.reduce((max, row) => Math.max(max, Number.parseInt(row.version_number, 10) || 0), 0);
return [{ json: { ...ctx, version_number: maxVersion + 1 } }];

const product = $input.all().map(item => item.json).find(row => String(row?.id) === '1369');
if (!product) throw new Error('FB_FAQ_INTELLICAD_PRODUCT_1369_NOT_FOUND');
const sheet = $('FB FAQ - Normalize + Deduplicate Sheet').first().json;
if (!Array.isArray(sheet.candidates) || !sheet.candidates.length) throw new Error('FB_FAQ_INTELLICAD_NO_CANDIDATES');
const sourceUrl = 'https://docs.google.com/spreadsheets/d/1gDdtPwZDQQCWX1pF04NXWgHPh40WiU0OZ6Fj-FoOjR0/edit#gid=0';
function hashText(str) {
  let h1 = 0xdeadbeef ^ str.length, h2 = 0x41c6ce57 ^ str.length;
  for (let i = 0, ch; i < str.length; i++) { ch = str.charCodeAt(i); h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0');
}
return [{ json: {
  ...sheet,
  product_id: 1369,
  product_code: product.code,
  product_name: 'CMS IntelliCAD',
  title: 'FAQ hội thoại Facebook IntelliCAD',
  document_type: 'faq',
  language_code: 'vi',
  source_type: 'google_sheets',
  source_url: sourceUrl,
  file_name: 'Cuộc trò chuyện Facebook IntelliCAD - Q&A',
  mime_type: 'application/vnd.google-apps.spreadsheet',
  document_identity_hash: hashText('1369|google_sheets|' + sourceUrl + '|faq'),
  metadata: { content_type: 'faq', source: 'facebook_conversation', product: 'CMS IntelliCAD', product_code: product.code, incremental: true },
} }];

const modelRows = $input.all().map(item => item.json).filter(row => row?.id);
const modelId = modelRows[0]?.id;
const src = $('FB FAQ - Loop Embeddings').item.json;

if (!modelId) throw new Error('FB_FAQ_EMBEDDING_MODEL_NOT_FOUND');
if (!src?.chunk_id || !String(src.content || '').trim()) {
  throw new Error('FB_FAQ_EMBEDDING_LOOP_CONTEXT_INVALID');
}

return [{ json: { ...src, embedding_model_id: modelId } }];

const src = $json;
if (!src?.chunk_id || !src?.embedding_model_id) {
  throw new Error('FB_FAQ_EMBEDDING_INSERT_CONTEXT_INVALID');
}
if (!Array.isArray(src.embedding) || src.embedding.length !== 1024) {
  throw new Error('FB_FAQ_EMBEDDING_STORAGE_DIMENSION_INVALID');
}

return [{
  json: {
    chunk_id: src.chunk_id,
    embedding_model_id: src.embedding_model_id,
    embedding: JSON.stringify(src.embedding),
    content_hash: src.content_hash,
    document_version_id: src.document_version_id,
    is_active: true,
    is_retrievable: true,
    metadata: {
      content_type: 'faq',
      source: 'facebook_conversation',
      product: 'IntelliCAD',
      customer_name_included: false,
      product_id: src.product_id,
      document_version_id: src.document_version_id,
      chunk_index: src.chunk_index,
      language_code: src.language_code,
      embedding_model: 'qwen3-embedding-8b',
      source_dimension: 4096,
      embedding_dimension: 1024,
      dimension_reduction: 'mrl_prefix_l2_normalized',
      embedding_provider: 'cic-ai-api'
    }
  }
}];

const input = $input.all().map(item => item.json);
const rows = input.flatMap(value => Array.isArray(value) ? value : (Array.isArray(value?.data) ? value.data : (value?.id ? [value] : [])));
const modelId = $('FB FAQ - Get Audit Embedding Model').first().json.id;
const planned = $('FB FAQ - Plan Incremental FAQ').all().map(item => item.json);
const indexes = rows.map(row => Number(row.chunk_index)).sort((a, b) => a - b);
const bad = [];
for (const row of rows) {
  const embeddings = Array.isArray(row.product_chunk_embeddings) ? row.product_chunk_embeddings : [];
  const valid = embeddings.filter(embedding => embedding.embedding_model_id === modelId && embedding.is_active === true && embedding.is_retrievable === true && embedding.content_hash === row.content_hash);
  if (valid.length !== 1) bad.push({ chunk_index: row.chunk_index, valid_embeddings: valid.length });
}
const contiguous = indexes.length > 0 && indexes.every((value, index) => value === index);
if (!rows.length || !contiguous || bad.length) throw new Error('FB_FAQ_EMBEDDING_COVERAGE_INCOMPLETE actual=' + rows.length + ' contiguous=' + contiguous + ' bad=' + JSON.stringify(bad));
return [{ json: {
  document_version_id: planned.find(row => row.document_version_id)?.document_version_id,
  chunk_count: rows.length, embedding_count: rows.length, coverage_complete: true,
  work_count: planned.filter(row => row.has_work).length,
  new_faq_count: planned.filter(row => row.action === 'insert_chunk').length,
  repaired_embedding_count: planned.filter(row => row.action === 'embed_existing').length,
} }];

const rows = $input.all().map((item, index) => ({ row: item.json ?? {}, input_index: index }));
function key(value) {
  return String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}
function clean(value) {
  return String(value ?? '').normalize('NFC').replace(/\r\n?/g, '\n').split('\n').map(line => line.trim().replace(/[ \t]+/g, ' ')).join('\n').replace(/\n{3,}/g, '\n\n').trim();
}
function field(row, wanted) {
  for (const [name, value] of Object.entries(row)) if (wanted.includes(key(name))) return clean(value);
  return '';
}
function hashText(str) {
  let h1 = 0xdeadbeef ^ str.length, h2 = 0x41c6ce57 ^ str.length;
  for (let i = 0, ch; i < str.length; i++) { ch = str.charCodeAt(i); h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0');
}
function splitAnswer(question, answer, maxChars = 4500) {
  const prefix = 'Câu hỏi: ' + question + '\nCâu trả lời: ';
  if ((prefix + answer).length <= maxChars) return [answer];
  const maxBody = Math.max(800, maxChars - prefix.length - 100);
  const parts = [];
  let start = 0;
  while (start < answer.length) {
    let end = Math.min(start + maxBody, answer.length);
    if (end < answer.length) {
      const slice = answer.slice(start, end);
      const best = Math.max(slice.lastIndexOf('\n\n'), slice.lastIndexOf('. '), slice.lastIndexOf('; '), slice.lastIndexOf(', '), slice.lastIndexOf(' '));
      if (best > maxBody * 0.6) end = start + best + 1;
    }
    parts.push(answer.slice(start, end).trim());
    start = end;
  }
  return parts.filter(Boolean);
}
const unique = new Map();
let invalidRows = 0, duplicateRows = 0;
for (const { row, input_index } of rows) {
  const question = field(row, ['cau hoi', 'question']);
  const answer = field(row, ['cau tra loi', 'tra loi', 'answer']);
  if (!question || !answer) { invalidRows++; continue; }
  const parts = splitAnswer(question, answer);
  for (let partIndex = 0; partIndex < parts.length; partIndex++) {
    const partLabel = parts.length > 1 ? ' (Phần ' + (partIndex + 1) + '/' + parts.length + ')' : '';
    const content = 'Câu hỏi' + partLabel + ': ' + question + '\nCâu trả lời: ' + parts[partIndex];
    const contentHash = hashText('faq-intellicad-v1\n' + clean(content));
    if (unique.has(contentHash)) { duplicateRows++; continue; }
    unique.set(contentHash, {
      content,
      content_hash: contentHash,
      source_row_number: Number(row.row_number ?? row.rowNumber ?? input_index + 2),
      part_index: partIndex,
      part_count: parts.length,
    });
  }
}
const candidates = [...unique.values()];
if (!candidates.length) throw new Error('FB_FAQ_INTELLICAD_NO_VALID_ROWS');
const documentText = candidates.map(item => item.content).join('\n\n---\n\n');
const sheetContentHash = hashText(candidates.map(item => item.content_hash).sort().join('|'));
return [{ json: {
  candidates,
  document_text: documentText,
  sheet_content_hash: sheetContentHash,
  sheet_row_count: rows.length,
  valid_faq_count: candidates.length,
  invalid_row_count: invalidRows,
  duplicate_in_sheet_count: duplicateRows,
} }];

const rows = $input.all().map(item => item.json).filter(row => row?.id);
if (!rows.length) return [{ json: { version_exists: false } }];
rows.sort((a, b) => Number(b.version_number || 0) - Number(a.version_number || 0) || String(b.created_at || '').localeCompare(String(a.created_at || '')));
return [{ json: { ...rows[0], version_exists: true } }];

const ctx = $('FB FAQ - Resolve Document ID').first().json;
const current = $('FB FAQ - Select Latest FAQ Version').first().json;
const modelId = $('FB FAQ - Get Audit Embedding Model').first().json.id;
if (!modelId) throw new Error('FB_FAQ_EMBEDDING_MODEL_NOT_FOUND');
const input = $input.all().map(item => item.json);
const flat = input.flatMap(value => Array.isArray(value) ? value : (Array.isArray(value?.data) ? value.data : [value]));
const versionId = current.version_exists ? current.id : flat.find(row => row?.id && row?.document_id === ctx.document_id)?.id;
if (!versionId) throw new Error('FB_FAQ_DOCUMENT_VERSION_ID_MISSING');
const existing = current.version_exists
  ? flat.filter(row => row?.id && row.document_version_id === versionId && Number.isInteger(Number(row.chunk_index)))
  : [];
const byHash = new Map();
for (const row of existing) if (row.content_hash && !byHash.has(row.content_hash)) byHash.set(row.content_hash, row);
let nextIndex = existing.reduce((max, row) => Math.max(max, Number(row.chunk_index)), -1) + 1;
const work = [];
let alreadyPresent = 0;
for (const faq of ctx.candidates) {
  const row = byHash.get(faq.content_hash);
  if (!row) {
    work.push({ json: {
      action: 'insert_chunk', has_work: true, needs_chunk_insert: true,
      document_version_id: versionId, product_id: ctx.product_id, chunk_index: nextIndex++,
      section: 'FAQ_HOI_THOAI_FACEBOOK_INTELLICAD',
      title: 'FAQ hội thoại Facebook IntelliCAD', content: faq.content,
      language_code: 'vi', content_hash: faq.content_hash,
      metadata: { ...ctx.metadata, source_row_number: faq.source_row_number, part_index: faq.part_index, part_count: faq.part_count, faq_content_hash: faq.content_hash },
    } });
    continue;
  }
  alreadyPresent++;
  const embeddings = Array.isArray(row.product_chunk_embeddings) ? row.product_chunk_embeddings : [];
  const valid = embeddings.filter(embedding => embedding.embedding_model_id === modelId && embedding.content_hash === row.content_hash && embedding.is_active === true && embedding.is_retrievable === true);
  if (valid.length !== 1) {
    work.push({ json: { ...row, action: 'embed_existing', has_work: true, needs_chunk_insert: false } });
  }
}
if (work.length) return work;
return [{ json: {
  action: 'skip', has_work: false, needs_chunk_insert: false,
  document_id: ctx.document_id, document_version_id: versionId,
  sheet_faq_count: ctx.candidates.length, already_present_count: alreadyPresent,
  duplicate_in_sheet_count: ctx.duplicate_in_sheet_count,
  reason: 'all FAQ rows already exist and have valid embeddings',
} }];

const ctx = $('FB FAQ - Resolve Document ID').first().json;
const validation = $('FB FAQ - Validate Embedding Coverage').first().json;
return [{ json: {
  status: validation.work_count > 0 ? 'completed' : 'skipped',
  reason: validation.work_count > 0 ? 'new or incomplete IntelliCAD FAQ processed' : 'all IntelliCAD FAQ rows already exist',
  product_id: ctx.product_id, document_id: ctx.document_id,
  document_version_id: validation.document_version_id,
  sheet_faq_count: ctx.valid_faq_count,
  new_faq_count: validation.new_faq_count,
  repaired_embedding_count: validation.repaired_embedding_count,
  duplicate_in_sheet_count: ctx.duplicate_in_sheet_count,
  total_chunk_count: validation.chunk_count,
} }];

